const escapeHTML=(v)=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const formatMoney=(n)=>new Intl.NumberFormat('vi-VN').format(n)+'đ';
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2500)}
function storeLocal(){localStorage.setItem('angihomnay-favorites',JSON.stringify(savedIds));localStorage.setItem('angihomnay-week',JSON.stringify(weeklyPlan));localStorage.setItem('angihomnay-reviews',JSON.stringify(reviews))}
function setSync(label,mode=''){const s=$('#syncStatus');s.className=`sync-status ${mode}`;s.querySelector('span').textContent=label}
function getDish(id){return dishes.find(d=>d.id===id)}
function imageUrl(d,w=760){if(d.photoLocal)return d.photoLocal;if(d.photoThumb)return d.photoThumb;if(d.photoFile)return `https://commons.wikimedia.org/wiki/Special:FilePath/${encodeURIComponent(d.photoFile)}?width=${w}`;return 'data:image/gif;base64,R0lGODlhAQABAAD/ACwAAAAAAQABAAACADs='}
function distanceKm(a,b,c,d){const rad=n=>n*Math.PI/180;const deltaLat=rad(c-a),deltaLon=rad(d-b);const h=Math.sin(deltaLat/2)**2+Math.cos(rad(a))*Math.cos(rad(c))*Math.sin(deltaLon/2)**2;return 6371*2*Math.atan2(Math.sqrt(h),Math.sqrt(1-h))}
function renderPlaces(){const region=$('#regionSelect').value;if(nearbyPlaces.length){$('#placeGrid').innerHTML=nearbyPlaces.map(p=>{const mapUrl=`https://www.google.com/maps/search/?api=1&query=${p.lat},${p.lon}`,osmMapUrl=`https://www.openstreetmap.org/?mlat=${p.lat}&mlon=${p.lon}#map=17/${p.lat}/${p.lon}`,osmSourceUrl=`https://www.openstreetmap.org/${p.type}/${p.id}`,address=p.address||'Địa chỉ đường/phường chưa có trong bản đồ; hãy xem vị trí trên bản đồ.';return `<article class="place-card"><div class="place-card-top"><span class="place-region">Cách bạn ${p.distance.toFixed(1)} km</span><span class="place-dish">${escapeHTML(p.kind)}</span></div><h3>${escapeHTML(p.name)}</h3><p class="place-address">📍 ${escapeHTML(address)}</p><div class="place-links"><a href="${mapUrl}" target="_blank" rel="noopener">Google Maps ↗</a><a href="${osmMapUrl}" target="_blank" rel="noopener">OpenStreetMap ↗</a><a href="${osmSourceUrl}" target="_blank" rel="noopener">Dữ liệu OSM ↗</a></div></article>`}).join('');return}const items=featuredPlaces.filter(p=>region==='all'||p.region===region);$('#placeGrid').innerHTML=items.map(p=>{const query=`${p.name} ${p.address}`,mapUrl=`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(query)}`,osmMapUrl=`https://www.openstreetmap.org/search?query=${encodeURIComponent(query)}`;return `<article class="place-card"><div class="place-card-top"><span class="place-region">${regionLabels[p.region]}</span><span class="place-dish">${escapeHTML(p.dish)}</span></div><h3>${escapeHTML(p.name)}</h3><p class="place-address">📍 ${escapeHTML(p.address)}</p><div class="place-links"><a href="${mapUrl}" target="_blank" rel="noopener">Google Maps ↗</a><a href="${osmMapUrl}" target="_blank" rel="noopener">OpenStreetMap ↗</a><a href="${p.source}" target="_blank" rel="noopener">Nguồn địa chỉ ↗</a></div></article>`}).join('')}
function renderNearbyMapFallback(lat,lon,description){const googleUrl=`https://www.google.com/maps/search/?api=1&query=${lat},${lon}`,osmUrl=`https://www.openstreetmap.org/?mlat=${lat}&mlon=${lon}#map=16/${lat}/${lon}`;$('#placeGrid').innerHTML=`<article class="place-card"><h3>Tìm quán quanh vị trí của bạn</h3><p class="place-address">${description}</p><div class="place-links"><a target="_blank" rel="noopener" href="${googleUrl}">Google Maps ↗</a><a target="_blank" rel="noopener" href="${osmUrl}">OpenStreetMap ↗</a></div></article>`}
async function findNearbyPlaces(coords){const status=$('#locationStatus'),button=$('#locationButton'),{latitude:lat,longitude:lon}=coords;userCoords={lat,lon};nearbyPlaces=[];$('#placeGrid').innerHTML='';status.textContent='Đã lấy được vị trí. Đang tìm quán ăn trong bán kính 3 km…';const query=`[out:json][timeout:12];(nwr(around:3000,${lat},${lon})["amenity"~"restaurant|cafe|fast_food|food_court"]["name"];);out center 60;`,endpoints=['https://overpass-api.de/api/interpreter','https://overpass.private.coffee/api/interpreter'];let lastError;try{let data;for(const endpoint of endpoints){try{const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body:new URLSearchParams({data:query}),signal:AbortSignal.timeout(14000)});if(!response.ok)throw new Error(`Overpass HTTP ${response.status}`);data=await response.json();break}catch(error){lastError=error;console.warn('Nearby OSM endpoint failed',endpoint,error)}}if(!data)throw lastError||new Error('Không có dịch vụ bản đồ phản hồi');nearbyPlaces=(data.elements||[]).map(el=>{const t=el.tags||{},point=el.center||el,elLat=el.lat??point.lat,elLon=el.lon??point.lon;if(typeof elLat!=='number'||typeof elLon!=='number')return null;const address=t['addr:full']||[t['addr:housenumber'],t['addr:street'],t['addr:suburb']||t['addr:district'],t['addr:city']||t['addr:province']].filter(Boolean).join(', ');return{id:el.id,type:el.type,name:t.name,kind:t.cuisine||t.amenity||'Địa điểm ăn uống',address,lat:elLat,lon:elLon,distance:distanceKm(lat,lon,elLat,elLon)}}).filter(p=>p && p.distance<=3).sort((a,b)=>a.distance-b.distance).slice(0,18);if(!nearbyPlaces.length){status.textContent='Chưa tìm thấy quán được ghi tên trong bán kính 3 km. Mở bản đồ quanh vị trí để tìm thêm.';renderNearbyMapFallback(lat,lon,'OpenStreetMap chưa ghi nhận quán ăn gần đây; bạn vẫn có thể tìm trực tiếp trên bản đồ.');return}renderPlaces();status.textContent=`Tìm thấy ${nearbyPlaces.length} địa điểm ăn uống gần bạn trong dữ liệu OpenStreetMap. Thông tin có thể thiếu hoặc cũ; kiểm tra giờ mở cửa và món bán trước khi đi.`}catch(error){console.warn('Nearby OSM lookup failed',error);status.textContent='Dịch vụ tìm danh sách quán đang bận. Bạn vẫn có thể mở Google Maps hoặc OpenStreetMap quanh vị trí.';renderNearbyMapFallback(lat,lon,'Danh sách quán tạm thời không phản hồi. Mở một trong hai bản đồ để tiếp tục tìm kiếm.')}finally{button.disabled=false;button.textContent='📍 Tìm quán gần tôi'}}
function detectRegionFromLocation(){const status=$('#locationStatus'),button=$('#locationButton');const reset=()=>{button.disabled=false;button.textContent='📍 Tìm quán gần tôi'};if(!window.isSecureContext){status.textContent='Định vị cần kết nối HTTPS. Hãy mở https://angihomnayyy.netlify.app/ rồi thử lại.';return}if(!navigator.geolocation){status.textContent='Trình duyệt này không hỗ trợ định vị. Hãy mở trang bằng Chrome, Edge hoặc Safari.';return}button.disabled=true;button.textContent='Đang xác định vị trí…';nearbyPlaces=[];$('#placeGrid').innerHTML='';status.textContent='Hãy cho phép truy cập vị trí khi trình duyệt hỏi. Tọa độ sẽ được gửi tới OpenStreetMap để tìm quán trong 3 km.';navigator.geolocation.getCurrentPosition(({coords})=>{if(!Number.isFinite(coords.latitude)||!Number.isFinite(coords.longitude)){reset();status.textContent='Thiết bị trả về vị trí không hợp lệ. Hãy thử lại.';return}if(Number.isFinite(coords.accuracy)&&coords.accuracy>3000){reset();status.textContent='Vị trí hiện tại có sai số lớn hơn 3 km, chưa đủ chính xác để tìm quán gần bạn. Bật vị trí của thiết bị hoặc thử trên điện thoại.';return}findNearbyPlaces(coords)},error=>{reset();const messages={1:'Quyền vị trí đang bị chặn. Cho phép vị trí cho trang web trong cài đặt trình duyệt và bật dịch vụ vị trí của thiết bị, rồi thử lại.',2:'Thiết bị không xác định được vị trí. Kiểm tra dịch vụ vị trí của Windows/điện thoại, kết nối mạng hoặc thử trên điện thoại.',3:'Quá thời gian lấy vị trí (25 giây). Bật dịch vụ vị trí của thiết bị rồi bấm tìm lại.'};status.textContent=messages[error.code]||'Không lấy được vị trí. Hãy thử lại trên trình duyệt khác.'},{enableHighAccuracy:true,timeout:25000,maximumAge:60000})}
function filteredDishes(){return dishes.filter(d=>(mood==='all'||d.mood.includes(mood))&&d.price<=maxPrice&&`${d.name} ${d.category} ${d.description}`.toLocaleLowerCase('vi').includes(search))}
function renderDishes(){const filtered=filteredDishes(),shown=expanded?filtered:filtered.slice(0,12);$('#dishGrid').innerHTML=shown.map(d=>{const saved=savedIds.includes(d.id);const cardReviews=reviews[d.id]||[];const average=cardReviews.length?cardReviews.reduce((n,r)=>n+r.rating,0)/cardReviews.length:d.rating;const count=d.votes+cardReviews.length;const credit=d.photoGenerated?'<span class="photo-status">Ảnh minh họa AI</span>':d.photoFile||d.photoThumb?`<span class="photo-credit"><a href="${d.photoSource}" target="_blank" rel="noopener" title="Mở trang nguồn ảnh">© ${escapeHTML(d.photoAuthor)}</a><a href="${d.photoLicenseUrl}" target="_blank" rel="noopener" title="Xem điều khoản giấy phép">${escapeHTML(d.photoLicense)}</a></span>`:d.photoMissing?'<span class="photo-status">Chưa tìm được ảnh khớp món</span>':'<span class="photo-status">Ảnh món đang được bổ sung</span>';return `<article class="dish-card" data-dish="${d.id}" tabindex="0" aria-label="Xem ${escapeHTML(d.name)}"><div class="dish-image ${d.photoMissing||(!d.photoFile&&!d.photoThumb)?'no-photo':''}" style="background-position:${d.position}"><img class="dish-photo" src="${imageUrl(d)}" alt="${d.photoGenerated?'Ảnh minh họa AI: ':'Ảnh '}${escapeHTML(d.name)}" loading="lazy" onerror="this.hidden=true;this.parentElement.classList.add('no-photo')"><span class="image-fallback" aria-hidden="true">${d.icon}</span><span class="dish-badge">${escapeHTML(d.badge)}</span>${credit}<button class="favorite-button ${saved?'saved':''}" data-favorite="${d.id}" aria-label="${saved?'Bỏ lưu':'Lưu'} ${escapeHTML(d.name)}">${saved?'♥':'♡'}</button></div><div class="dish-card-body"><span class="dish-category">${escapeHTML(d.category)}</span><h3>${escapeHTML(d.name)}</h3><p class="dish-description">${escapeHTML(d.description)}</p><div class="dish-meta"><span class="dish-meta-left"><span class="dish-time">${d.minutes} phút</span><span>◉ ${escapeHTML(d.mood.includes('light')?'Ăn nhẹ':d.mood.includes('quick')?'Nhanh gọn':'Ăn no')}</span></span><span class="dish-cost">${formatMoney(d.price)}</span></div><div class="dish-rating"><span>★</span> ${average.toFixed(1)} <span style="color:#aba398">(${count} đánh giá)</span></div></div></article>`}).join('');$('#noResults').hidden=shown.length>0;$('#dishGrid').hidden=!shown.length;$('#showMoreBtn').hidden=filtered.length<=12;$('#showMoreBtn').innerHTML=expanded?'Thu gọn <span>↑</span>':'Xem tất cả '+filtered.length+' món <span>→</span>'}
function drawReviews(id){const rs=reviews[id]||[];const avg=rs.length?rs.reduce((a,r)=>a+r.rating,0)/rs.length:null;$('#ratingSummary').textContent=rs.length?`${avg.toFixed(1)} · ${rs.length} đánh giá`:'Chưa có đánh giá';$('#reviews').innerHTML=rs.slice(0,5).map(r=>`<div class="review-item"><strong>${escapeHTML(r.author||'Thành viên')}</strong><span>${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</span><div>${escapeHTML(r.comment)}</div></div>`).join('')}
function openDish(id){const d=getDish(id);if(!d)return;activeDish=id;$('#modalImage').style.backgroundImage=`url('${imageUrl(d,1000)}')`;$('#modalCategory').textContent=d.category+(d.photoGenerated?' · Ảnh minh họa AI':'');$('#modalName').textContent=d.name;$('#nearbyDishLink').href='https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(d.name+' gần đây');$('#nearbyDishLink').setAttribute('aria-label','Tìm '+d.name+' gần đây trên Google Maps (mở thẻ mới)');$('#modalMeta').innerHTML=`<span>◷ ${d.minutes} phút</span><span>♧ ${formatMoney(d.price)} / người</span><span>★ ${d.rating} (${d.votes} lượt)</span>`;$('#modalDescription').textContent=d.description+' Một gợi ý vừa ngon vừa hợp nhịp sống bận rộn.';$('#modalTags').innerHTML=d.tags.map(t=>`<span>${escapeHTML(t)}</span>`).join('');$('#modalFavorite').classList.toggle('saved',savedIds.includes(id));$('#modalFavorite').textContent=savedIds.includes(id)?'♥':'♡';$('#reviewForm').classList.remove('open');$('#reviewText').value='';pickedRating=5;renderRatingPicker();drawReviews(id);kitchen?.renderRecipe(id);openDialog($('#dishModal'));if(remoteReady)fetchReviews(id).then(()=>{if(activeDish===id){drawReviews(id);renderDishes()}})}
function openDialog(d){if(typeof d.showModal==='function')d.showModal();else d.setAttribute('open','')}
function closeDialog(d){if(typeof d.close==='function')d.close();else d.removeAttribute('open')}
function renderRatingPicker(){document.querySelectorAll('#ratingPicker button').forEach(b=>b.classList.toggle('selected',Number(b.dataset.rating)<=pickedRating))}
function toggleFavorite(id){if(savedIds.includes(id))savedIds=savedIds.filter(x=>x!==id);else savedIds.push(id);storeLocal();renderDishes();if(activeDish===id){$('#modalFavorite').classList.toggle('saved',savedIds.includes(id));$('#modalFavorite').textContent=savedIds.includes(id)?'♥':'♡'}if(user&&supabase)syncFavorite(id,savedIds.includes(id));else toast(savedIds.includes(id)?'Đã lưu món vào yêu thích trên thiết bị này.':'Đã bỏ món khỏi danh sách yêu thích.')}
async function syncFavorite(id,isSaved){if(!remoteReady||!user)return;const result=isSaved?await supabase.from('favorites').upsert({user_id:user.id,dish_id:id},{onConflict:'user_id,dish_id'}):await supabase.from('favorites').delete().eq('user_id',user.id).eq('dish_id',id);if(result.error)toast('Chưa đồng bộ được món này. Kiểm tra thiết lập Supabase nhé.');else setSync('Đã đồng bộ','sync-on')}
function mondayDate(){const d=new Date();d.setHours(0,0,0,0);const day=(d.getDay()+6)%7;d.setDate(d.getDate()-day);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function renderWeek(){const options='<option value="">Chọn món…</option>'+dishes.map(d=>`<option value="${d.id}">${escapeHTML(d.name)} · ${formatMoney(d.price)}</option>`).join('');$('#weekList').innerHTML=dayLabels.map((day,i)=>`<label class="week-row"><span>${day.toLocaleUpperCase('vi')}</span><select data-day="${i}">${options}</select><button type="button" data-clear-day="${i}" aria-label="Xóa món ${day}">×</button></label>`).join('');document.querySelectorAll('[data-day]').forEach(s=>s.value=weeklyPlan[Number(s.dataset.day)]||'');$('#plannerAuthNote').textContent=user?'Kế hoạch sẽ đồng bộ với tài khoản của bạn.':'Bản dùng thử lưu kế hoạch trên trình duyệt. Đăng nhập để đồng bộ giữa các thiết bị.'}
function openPlanner(){renderWeek();openDialog($('#plannerModal'))}
async function savePlanner(){weeklyPlan=Array(7).fill('').map((_,i)=>$(`[data-day="${i}"]`).value);storeLocal();if(user&&remoteReady){const{error}=await supabase.from('weekly_plans').upsert({user_id:user.id,week_start:mondayDate(),meals:weeklyPlan},{onConflict:'user_id,week_start'});if(error){toast('Không lưu được kế hoạch. Hãy kiểm tra bảng dữ liệu.');return}setSync('Đã đồng bộ','sync-on');toast('Kế hoạch tuần đã đồng bộ!')}else toast('Đã lưu kế hoạch trên thiết bị này. Đăng nhập để đồng bộ giữa thiết bị.');closeDialog($('#plannerModal'))}
async function sendReview(event){event.preventDefault();if(!user){$('#reviewAuthHint').textContent='Đăng nhập bằng email để gửi đánh giá được đồng bộ.';openDialog($('#accountModal'));return}const comment=$('#reviewText').value.trim();if(!comment)return;const item={rating:pickedRating,comment,author:'Thành viên',created_at:new Date().toISOString()};if(remoteReady){const{error}=await supabase.from('food_reviews').insert({dish_id:activeDish,user_id:user.id,rating:pickedRating,comment});if(error){toast('Chưa gửi được đánh giá. Kiểm tra cấu hình cơ sở dữ liệu.');return}await fetchReviews(activeDish);toast('Đánh giá đã được chia sẻ!')}else{reviews[activeDish]=[item,...(reviews[activeDish]||[])].slice(0,5);storeLocal();toast('Đã lưu đánh giá trên thiết bị này.')}drawReviews(activeDish);renderDishes();$('#reviewForm').classList.remove('open')}
async function fetchReviews(dishId){if(!remoteReady)return;const{data,error}=await supabase.from('public_reviews').select('rating,comment,created_at').eq('dish_id',dishId).order('created_at',{ascending:false}).limit(20);if(!error){reviews[dishId]=(data||[]).map(r=>({...r,author:'Thành viên'}));storeLocal()}}
async function syncAccountData(){if(!remoteReady||!user)return;setSync('Đang đồng bộ…','');const[favoritesResult,planResult]=await Promise.all([supabase.from('favorites').select('dish_id').eq('user_id',user.id),supabase.from('weekly_plans').select('meals').eq('user_id',user.id).eq('week_start',mondayDate()).maybeSingle()]);if(favoritesResult.error||planResult.error){setSync('Cần kiểm tra kết nối','sync-offline');return}const remoteIds=(favoritesResult.data||[]).map(x=>x.dish_id);const localIds=savedIds.filter(x=>!remoteIds.includes(x));savedIds=[...new Set([...savedIds,...remoteIds])];if(localIds.length)await supabase.from('favorites').upsert(localIds.map(dish_id=>({user_id:user.id,dish_id})),{onConflict:'user_id,dish_id'});if(planResult.data?.meals)weeklyPlan=planResult.data.meals;else if(weeklyPlan.some(Boolean))await supabase.from('weekly_plans').upsert({user_id:user.id,week_start:mondayDate(),meals:weeklyPlan},{onConflict:'user_id,week_start'});storeLocal();renderDishes();setSync('Đã đồng bộ','sync-on')}
async function loadSupabase(){const cfg=window.APP_CONFIG||{};if(!cfg.supabaseUrl||!cfg.supabaseAnonKey){setSync('Đang lưu trên máy');$('#authMessage').textContent='Bản demo chưa kết nối cơ sở dữ liệu. Hãy theo hướng dẫn Supabase trong README để bật đăng nhập và đồng bộ.';return}try{const{createClient}=await import('https://esm.sh/@supabase/supabase-js@2');supabase=createClient(cfg.supabaseUrl,cfg.supabaseAnonKey);remoteReady=true;const{data}=await supabase.auth.getSession();user=data.session?.user||null;renderAccount();if(user)await syncAccountData();else setSync('Đăng nhập để đồng bộ');supabase.auth.onAuthStateChange((_event,session)=>{user=session?.user||null;renderAccount();if(user)queueMicrotask(()=>syncAccountData());else setSync('Đăng nhập để đồng bộ')});}catch(error){console.warn('Supabase connection unavailable',error);remoteReady=false;setSync('Đang lưu trên máy','sync-offline')}}
function renderAccount(){const b=$('#accountButton'),email=user?.email||'Tài khoản';b.innerHTML=user?`${escapeHTML(email.split('@')[0])} <span>↗</span>`:'Đăng nhập <span>↗</span>';if(user)setSync('Đã đăng nhập','sync-on')}
async function signIn(event){event.preventDefault();const email=$('#emailInput').value.trim(),message=$('#authMessage'),submit=$('.auth-submit');if(!supabase){message.textContent='Chưa kết nối Supabase. Hãy kiểm tra config.js và hướng dẫn URL đăng nhập trong README.';return}if(!email){message.textContent='Nhập email hợp lệ rồi thử lại.';return}submit.disabled=true;message.textContent='Đang gửi liên kết đăng nhập…';try{const redirectTo=new URL(window.location.pathname,window.location.origin).href,{error}=await supabase.auth.signInWithOtp({email,options:{emailRedirectTo:redirectTo}});if(error){const redirectError=/redirect|url configuration|allowlist/i.test(error.message);message.textContent=redirectError?`Supabase chưa cho phép địa chỉ ${redirectTo}. Thêm URL này trong Authentication → URL Configuration.`:`Không gửi được email: ${error.message}`;return}message.textContent='Đã gửi liên kết đăng nhập. Mở email trên cùng thiết bị rồi nhấn liên kết để quay lại trang này.'}catch(error){console.warn('Supabase email sign-in failed',error);message.textContent='Không kết nối được dịch vụ đăng nhập. Kiểm tra Internet rồi thử lại.'}finally{submit.disabled=false}}

renderDishes();
renderPlaces();
document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>closeDialog(b.closest('dialog'))));
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d)closeDialog(d)}));
document.querySelectorAll('.pill').forEach(b=>b.addEventListener('click',()=>{mood=b.dataset.mood;document.querySelectorAll('.pill').forEach(x=>x.classList.toggle('active',x===b));renderDishes()}));
$('#budgetFilter').addEventListener('change',e=>{maxPrice=Number(e.target.value);renderDishes()});$('#searchInput').addEventListener('input',e=>{search=e.target.value.trim().toLocaleLowerCase('vi');renderDishes()});
$('#resetFilters').addEventListener('click',()=>{mood='all';maxPrice=100000;search='';$('#budgetFilter').value='100000';$('#searchInput').value='';document.querySelectorAll('.pill').forEach(b=>b.classList.toggle('active',b.dataset.mood==='all'));renderDishes()});
$('#showMoreBtn').addEventListener('click',()=>{expanded=!expanded;renderDishes()});
$('#regionSelect').addEventListener('change',()=>{nearbyPlaces=[];const region=$('#regionSelect').value;$('#locationStatus').textContent=region==='all'?'Đang hiển thị quán tiêu biểu từ cả ba miền.':`Đang xem gợi ý ở ${regionLabels[region]}.`;renderPlaces()});$('#locationButton').addEventListener('click',detectRegionFromLocation);
$('#dishGrid').addEventListener('click',e=>{const fav=e.target.closest('[data-favorite]');if(fav){e.stopPropagation();toggleFavorite(fav.dataset.favorite);return}if(e.target.closest('.photo-download,.photo-credit')){e.stopPropagation();return}const card=e.target.closest('[data-dish]');if(card)openDish(card.dataset.dish)});$('#dishGrid').addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-dish]')){e.preventDefault();openDish(e.target.dataset.dish)}});
$('#surpriseBtn').addEventListener('click',()=>{const pool=filteredDishes();if(!pool.length){toast('Không có món phù hợp bộ lọc.');return}openDish(pool[Math.floor(Math.random()*pool.length)].id)});
$('#modalFavorite').addEventListener('click',()=>{if(activeDish)toggleFavorite(activeDish)});$('#reviewButton').addEventListener('click',()=>{$('#reviewForm').classList.toggle('open');$('#reviewText').focus()});$('#ratingPicker').addEventListener('click',e=>{const b=e.target.closest('[data-rating]');if(b){pickedRating=Number(b.dataset.rating);renderRatingPicker()}});$('#reviewForm').addEventListener('submit',sendReview);
$('#accountButton').addEventListener('click',()=>{if(user){if(confirm('Bạn muốn đăng xuất khỏi tài khoản?'))supabase.auth.signOut();return}openDialog($('#accountModal'))});$('#authForm').addEventListener('submit',signIn);
$('#plannerBtn').addEventListener('click',openPlanner);$('#savePlannerBtn').addEventListener('click',savePlanner);$('#weekList').addEventListener('change',e=>{if(e.target.matches('[data-day]'))weeklyPlan[Number(e.target.dataset.day)]=e.target.value});$('#weekList').addEventListener('click',e=>{const b=e.target.closest('[data-clear-day]');if(b){const i=Number(b.dataset.clearDay);weeklyPlan[i]='';$(`[data-day="${i}"]`).value=''}});
$('#mobileMenu').addEventListener('click',()=>{const nav=$('.desktop-nav');nav.classList.toggle('mobile-open');});document.querySelectorAll('.desktop-nav a').forEach(a=>a.addEventListener('click',()=>$('.desktop-nav').classList.remove('mobile-open')));
kitchen=initKitchen({dishes,escapeHTML,toast,openDialog,closeDialog,openDish,openPlanner,getActiveDish:()=>activeDish,getPlan:()=>weeklyPlan});
loadSupabase();
